using System;
using Rebellion.Game.Galaxy;
using Rebellion.Game.Units;
using Rebellion.SceneGraph;
using Rebellion.Simulation;

namespace Rebellion.AI.Demands
{
    /// <summary>
    /// Production demand categories generated by the AI.
    /// </summary>
    public enum AIProductionDemandKind
    {
        None,
        Colony,
        Mine,
        Refinery,
        ConstructionFacility,
        Shipyard,
        TrainingFacility,
        PlanetaryDefense,
        PlanetaryStarfighterReserve,
        FleetCapitalShip,
        FleetStarfighter,
        FleetRegiment,
        GarrisonRegimentReserve,
        SpecialForces,
        FleetSeedCapitalShip,
        ColonizationFleetSeedCapitalShip,
        BuildingUpgrade,
        IdleSpecialForces,
    }

    /// <summary>
    /// Strategic roles that a capital ship can fill for a production demand.
    /// </summary>
    public enum AICapitalShipProductionRole
    {
        None,

        General,

        TroopTransport,

        Bombardment,

        Interdiction,
    }

    /// <summary>
    /// Represents one AI production need.
    /// </summary>
    public sealed class AIProductionDemand
    {
        // Demand Identity.
        public string Id { get; }
        public AIProductionDemandKind Kind { get; }

        // Production Capability.
        public ManufacturingType ManufacturingType { get; }
        public BuildingType BuildingType { get; }
        public string ProductTypeId { get; }
        public AICapitalShipProductionRole CapitalShipRole { get; }
        public Building BuildingToReplace { get; }

        // Destination.
        public ContainerNode Destination { get; }
        public Planet DestinationPlanet => Destination as Planet;
        public Fleet DestinationFleet => Destination as Fleet;

        // Measured Need.
        public int QuantityNeeded { get; }
        public int DeficitCount { get; }
        public int TargetCount { get; }
        public int BaseDemandPercent { get; }
        public int CapitalFirepowerDeficit { get; }
        public int CombatStrengthDeficit { get; }
        public int StarfighterFirepowerDeficit { get; }
        public int StarfighterCapacityDeficit { get; }
        public int RegimentCapacityDeficit { get; }
        public int PlanetDestroyerDeficit { get; }
        public int BombardmentDeficit { get; }
        public int InterdictionDeficit { get; }
        public int EmbarkedRegimentDeficit { get; }
        public int EmbarkedStarfighterDeficit { get; }
        public int EscortDeficit { get; }
        public Planet ReferencePlanet { get; }
        public bool EstablishesInitialShield { get; }
        public bool IsEmergencyDefense { get; }
        public bool IsProductionFiller =>
            Kind == AIProductionDemandKind.IdleSpecialForces
            || Kind == AIProductionDemandKind.PlanetaryDefense && !IsEmergencyDefense;
        public bool UsesIdleShipyardCapacity { get; }
        public int InfrastructureHubIndex { get; }

        // Reserve Policy.
        public bool CanUseRefinedMaterialReserve =>
            Kind
                is AIProductionDemandKind.Mine
                    or AIProductionDemandKind.Refinery
                    or AIProductionDemandKind.ColonizationFleetSeedCapitalShip
            || DestinationFleet?.RoleType == FleetRoleType.Colonization;

        public bool UsesDefensiveReserve =>
            Kind
                is AIProductionDemandKind.PlanetaryDefense
                    or AIProductionDemandKind.PlanetaryStarfighterReserve
                    or AIProductionDemandKind.GarrisonRegimentReserve
                    or AIProductionDemandKind.TrainingFacility
                    or AIProductionDemandKind.BuildingUpgrade;

        public bool RestoresMaintenanceCapacity =>
            Kind is AIProductionDemandKind.Mine or AIProductionDemandKind.Refinery;

        /// <summary>
        /// Creates a production demand.
        /// </summary>
        /// <param name="id">Stable demand identifier.</param>
        /// <param name="kind">Demand kind.</param>
        /// <param name="manufacturingType">Manufacturing type required for the demand.</param>
        /// <param name="buildingType">Building type required for building demands.</param>
        /// <param name="destination">Container receiving the produced item.</param>
        /// <param name="quantityNeeded">Amount of demand still needed.</param>
        /// <param name="productTypeId">Exact product type required by the demand.</param>
        /// <param name="capitalShipRole">Capital ship role required by the demand.</param>
        /// <param name="buildingToReplace">Existing building replaced by an upgrade.</param>
        /// <param name="targetCount">Total capability target used to measure the deficit.</param>
        /// <param name="baseDemandPercent">Configured base urgency before scored considerations.</param>
        /// <param name="referencePlanet">Planet whose unmet need prompted this demand.</param>
        /// <param name="establishesInitialShield">Whether this demand establishes a planet's first shield.</param>
        /// <param name="deficitCount">Original unmet quantity before proposal batching.</param>
        /// <param name="usesIdleShipyardCapacity">Whether this is opportunistic work for an otherwise idle local shipyard.</param>
        /// <param name="capitalFirepowerDeficit">Unmet capital-target firepower.</param>
        /// <param name="starfighterFirepowerDeficit">Unmet fighter-target firepower.</param>
        /// <param name="starfighterCapacityDeficit">Unmet carried-starfighter capacity.</param>
        /// <param name="regimentCapacityDeficit">Unmet carried-regiment capacity.</param>
        /// <param name="planetDestroyerDeficit">Unmet planet-destroying ship count.</param>
        /// <param name="bombardmentDeficit">Unmet bombardment strength.</param>
        /// <param name="interdictionDeficit">Unmet interdiction capability count.</param>
        /// <param name="embarkedRegimentDeficit">Unmet embarked-regiment count.</param>
        /// <param name="embarkedStarfighterDeficit">Unmet embarked-starfighter count.</param>
        /// <param name="escortDeficit">Unmet armed escort count.</param>
        /// <param name="infrastructureHubIndex">Zero-based infrastructure hub position, or negative one when the demand is not for a hub.</param>
        /// <param name="combatStrengthDeficit">Unmet durability-adjusted combat strength.</param>
        /// <param name="isEmergencyDefense">Whether a known hostile fleet requires immediate static defense.</param>
        public AIProductionDemand(
            string id,
            AIProductionDemandKind kind,
            ManufacturingType manufacturingType,
            BuildingType buildingType,
            ContainerNode destination,
            int quantityNeeded,
            string productTypeId = null,
            AICapitalShipProductionRole capitalShipRole = AICapitalShipProductionRole.None,
            Building buildingToReplace = null,
            int targetCount = 0,
            int baseDemandPercent = 0,
            Planet referencePlanet = null,
            bool establishesInitialShield = false,
            int deficitCount = 0,
            bool usesIdleShipyardCapacity = false,
            int capitalFirepowerDeficit = 0,
            int starfighterFirepowerDeficit = 0,
            int starfighterCapacityDeficit = 0,
            int regimentCapacityDeficit = 0,
            int planetDestroyerDeficit = 0,
            int bombardmentDeficit = 0,
            int interdictionDeficit = 0,
            int embarkedRegimentDeficit = 0,
            int embarkedStarfighterDeficit = 0,
            int escortDeficit = 0,
            int infrastructureHubIndex = -1,
            int combatStrengthDeficit = 0,
            bool isEmergencyDefense = false
        )
        {
            Id = id;
            Kind = kind;
            ManufacturingType = manufacturingType;
            BuildingType = buildingType;
            Destination = destination;
            QuantityNeeded = quantityNeeded;
            DeficitCount = deficitCount > 0 ? deficitCount : quantityNeeded;
            TargetCount = targetCount;
            BaseDemandPercent = baseDemandPercent;
            ReferencePlanet = referencePlanet;
            EstablishesInitialShield = establishesInitialShield;
            IsEmergencyDefense = isEmergencyDefense;
            UsesIdleShipyardCapacity = usesIdleShipyardCapacity;
            ProductTypeId = productTypeId;
            CapitalShipRole = capitalShipRole;
            BuildingToReplace = buildingToReplace;
            CapitalFirepowerDeficit = Math.Max(0, capitalFirepowerDeficit);
            CombatStrengthDeficit = Math.Max(0, combatStrengthDeficit);
            StarfighterFirepowerDeficit = Math.Max(0, starfighterFirepowerDeficit);
            StarfighterCapacityDeficit = Math.Max(0, starfighterCapacityDeficit);
            RegimentCapacityDeficit = Math.Max(0, regimentCapacityDeficit);
            PlanetDestroyerDeficit = Math.Max(0, planetDestroyerDeficit);
            BombardmentDeficit = Math.Max(0, bombardmentDeficit);
            InterdictionDeficit = Math.Max(0, interdictionDeficit);
            EmbarkedRegimentDeficit = Math.Max(0, embarkedRegimentDeficit);
            EmbarkedStarfighterDeficit = Math.Max(0, embarkedStarfighterDeficit);
            EscortDeficit = Math.Max(0, escortDeficit);
            InfrastructureHubIndex = infrastructureHubIndex;
        }

        /// <summary>
        /// Copies this demand with a different immediately requested quantity.
        /// </summary>
        /// <param name="quantityNeeded">Quantity represented by the copied demand.</param>
        /// <returns>A demand with identical strategic identity and requirements.</returns>
        internal AIProductionDemand WithQuantity(int quantityNeeded)
        {
            return new AIProductionDemand(
                Id,
                Kind,
                ManufacturingType,
                BuildingType,
                Destination,
                quantityNeeded,
                ProductTypeId,
                CapitalShipRole,
                BuildingToReplace,
                TargetCount,
                BaseDemandPercent,
                ReferencePlanet,
                EstablishesInitialShield,
                DeficitCount,
                UsesIdleShipyardCapacity,
                CapitalFirepowerDeficit,
                StarfighterFirepowerDeficit,
                StarfighterCapacityDeficit,
                RegimentCapacityDeficit,
                PlanetDestroyerDeficit,
                BombardmentDeficit,
                InterdictionDeficit,
                EmbarkedRegimentDeficit,
                EmbarkedStarfighterDeficit,
                EscortDeficit,
                InfrastructureHubIndex,
                CombatStrengthDeficit,
                IsEmergencyDefense
            );
        }

        /// <summary>Copies a demand for one selected product without changing its strategic need.</summary>
        /// <param name="productTypeId">The selected product identifier.</param>
        /// <returns>The single-unit demand for that product.</returns>
        internal AIProductionDemand WithProduct(string productTypeId)
        {
            return new AIProductionDemand(
                Id,
                Kind,
                ManufacturingType,
                BuildingType,
                Destination,
                1,
                productTypeId,
                CapitalShipRole,
                BuildingToReplace,
                TargetCount,
                BaseDemandPercent,
                ReferencePlanet,
                EstablishesInitialShield,
                DeficitCount,
                UsesIdleShipyardCapacity,
                CapitalFirepowerDeficit,
                StarfighterFirepowerDeficit,
                StarfighterCapacityDeficit,
                RegimentCapacityDeficit,
                PlanetDestroyerDeficit,
                BombardmentDeficit,
                InterdictionDeficit,
                EmbarkedRegimentDeficit,
                EmbarkedStarfighterDeficit,
                EscortDeficit,
                InfrastructureHubIndex,
                CombatStrengthDeficit,
                IsEmergencyDefense
            );
        }

        /// <summary>Subtracts the capabilities supplied by a hypothetical hull from the remaining need.</summary>
        /// <param name="ship">The hull template assigned in this turn's plan.</param>
        /// <param name="combatStrength">The hull's projected combat strength for this demand.</param>
        /// <returns>The remaining need without creating or attaching any game entity.</returns>
        internal AIProductionDemand AfterPlanning(CapitalShip ship, int combatStrength)
        {
            return new AIProductionDemand(
                Id,
                Kind,
                ManufacturingType,
                BuildingType,
                Destination,
                QuantityNeeded,
                ProductTypeId,
                CapitalShipRole,
                BuildingToReplace,
                TargetCount,
                BaseDemandPercent,
                ReferencePlanet,
                EstablishesInitialShield,
                DeficitCount,
                UsesIdleShipyardCapacity,
                Math.Max(
                    0,
                    CapitalFirepowerDeficit
                        - SpaceCombatStrengthCalculator.GetCapitalShipFirepowerAgainstCapitalShips(
                            ship
                        )
                ),
                Math.Max(
                    0,
                    StarfighterFirepowerDeficit
                        - SpaceCombatStrengthCalculator.GetCapitalShipFirepowerAgainstStarfighters(
                            ship
                        )
                ),
                Math.Max(0, StarfighterCapacityDeficit - ship.StarfighterCapacity),
                Math.Max(0, RegimentCapacityDeficit - ship.RegimentCapacity),
                Math.Max(0, PlanetDestroyerDeficit - (ship.CanDestroyPlanets ? 1 : 0)),
                Math.Max(0, BombardmentDeficit - ship.Bombardment),
                Math.Max(0, InterdictionDeficit - (ship.HasGravityWell ? 1 : 0)),
                EmbarkedRegimentDeficit,
                EmbarkedStarfighterDeficit,
                Math.Max(
                    0,
                    EscortDeficit - (SpaceCombatStrengthCalculator.IsArmedEscort(ship) ? 1 : 0)
                ),
                InfrastructureHubIndex,
                Math.Max(0, CombatStrengthDeficit - combatStrength),
                IsEmergencyDefense
            );
        }

        /// <summary>
        /// Builds the canonical demand identifier for a faction, kind, and key parts.
        /// </summary>
        /// <param name="factionInstanceId">The owning faction instance id.</param>
        /// <param name="kind">The demand kind.</param>
        /// <param name="parts">Additional identifier segments.</param>
        /// <returns>The canonical demand identifier.</returns>
        internal static string CreateId(
            string factionInstanceId,
            AIProductionDemandKind kind,
            params object[] parts
        )
        {
            string id = $"production:{factionInstanceId}:{kind}";
            foreach (object part in parts)
                id += $":{part}";

            return id;
        }
    }
}
